  void CreateRoiCharts(){if(TrendGrid==null||DistributionGrid==null)return;var trend=new CartesianChart{LegendLocation=LegendLocation.Top,DisableAnimations=true,Hoverable=true,Foreground=new SolidColorBrush(Color.FromRgb(199,217,233)),Series=new SeriesCollection{new LineSeries{Title="Trung bình",Values=RoiAverageValues,LabelPoint=point=>FormatRoiDuration(point.Y),Stroke=new SolidColorBrush(Color.FromRgb(39,201,109)),Fill=Brushes.Transparent,StrokeThickness=2.5,PointGeometry=DefaultGeometries.Circle,PointGeometrySize=5}}};trend.AxisX.Add(new Axis{Labels=RoiTrendLabels,Foreground=new SolidColorBrush(Color.FromRgb(157,183,204)),FontSize=9,Separator=new Separator{Stroke=Brushes.Transparent}});trend.AxisY.Add(new Axis{Foreground=new SolidColorBrush(Color.FromRgb(157,183,204)),FontSize=9,LabelFormatter=FormatRoiDuration,Separator=new Separator{Stroke=new SolidColorBrush(Color.FromRgb(23,50,71)),StrokeDashArray=new DoubleCollection{3,3}}});ReplaceChart(TrendGrid,trend);var distribution=new CartesianChart{LegendLocation=LegendLocation.None,DisableAnimations=true,Hoverable=true,Foreground=new SolidColorBrush(Color.FromRgb(199,217,233)),Series=new SeriesCollection{new ColumnSeries{Title="Trong ngưỡng",Values=RoiDistributionUnderValues,Fill=new SolidColorBrush(Color.FromRgb(39,201,109)),MaxColumnWidth=26,ColumnPadding=5},new ColumnSeries{Title="Vượt ngưỡng",Values=RoiDistributionOverValues,Fill=new SolidColorBrush(Color.FromRgb(255,112,133)),MaxColumnWidth=26,ColumnPadding=5}}};distribution.AxisX.Add(new Axis{Labels=RoiDistributionLabels,Foreground=new SolidColorBrush(Color.FromRgb(157,183,204)),FontSize=9,Separator=new Separator{Stroke=Brushes.Transparent}});distribution.AxisY.Add(new Axis{MinValue=0,Foreground=new SolidColorBrush(Color.FromRgb(157,183,204)),FontSize=9,Separator=new Separator{Stroke=new SolidColorBrush(Color.FromRgb(23,50,71)),StrokeDashArray=new DoubleCollection{3,3}}});ReplaceChart(DistributionGrid,distribution);}
  void ReplaceChart(ListView placeholder,CartesianChart chart){var host=placeholder.Parent as Grid;if(host==null)return;chart.DisableAnimations=false;chart.AnimationsSpeed=TimeSpan.FromMilliseconds(420);chart.DataTooltip=new DefaultTooltip{Background=new SolidColorBrush(Color.FromRgb(10,28,43)),Foreground=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(54,123,255)),BorderThickness=new Thickness(1,1,1,1),Padding=new Thickness(12,8,12,8),ShowTitle=true,ShowSeries=true,Opacity=1};if(ReferenceEquals(placeholder,DistributionGrid))foreach(var series in chart.Series.OfType<ColumnSeries>()){series.MaxColumnWidth=42;series.ColumnPadding=0;}if(chart.AxisX.Count>0){var axis=chart.AxisX[0];axis.ShowLabels=true;axis.LabelsRotation=0;axis.Separator.Step=ReferenceEquals(placeholder,TrendGrid)?4:2;}if(ReferenceEquals(placeholder,DistributionGrid)&&chart.AxisX.Count>0){TimeSpan threshold;if(!TimeSpan.TryParseExact(ThresholdTimeText.Text,"mm\\:ss",CultureInfo.InvariantCulture,out threshold))threshold=TimeSpan.FromMinutes(5);chart.AxisX[0].Sections.Add(new LiveCharts.Wpf.AxisSection{Value=Math.Max(0,threshold.TotalMinutes-0.5),SectionWidth=0,Stroke=new SolidColorBrush(Color.FromRgb(255,122,26)),StrokeThickness=2,Label="Ngưỡng "+threshold.ToString(@"m\:ss")});}var row=Grid.GetRow(placeholder);host.Children.Remove(placeholder);Grid.SetRow(chart,row);host.Children.Add(chart);}
