  void FixCameraTrendAxes(){var chart=FindVisualChildren<CartesianChart>(_cameraAnalysisRoot).LastOrDefault();if(chart==null)return;var chartHost=chart.Parent as Grid;var chartBorder=chartHost?.Parent as Border;var panel=chartBorder?.Parent as Grid;if(panel!=null&&panel.ColumnDefinitions.Count>=3){panel.ColumnDefinitions[0].Width=new GridLength(2,GridUnitType.Star);panel.ColumnDefinitions[2].Width=new GridLength(1,GridUnitType.Star);}if(chart.AxisY.Count<2)chart.AxisY.Add(new Axis{Position=AxisPosition.RightTop,MinValue=0,MaxValue=100,Foreground=new SolidColorBrush(Color.FromRgb(157,183,204)),Separator=new Separator{Stroke=Brushes.Transparent}});chart.Hoverable=true;chart.DisableAnimations=false;chart.AnimationsSpeed=TimeSpan.FromMilliseconds(420);}
  static long LongestFilteredUnavailable(IEnumerable<ApiManager.CameraHealthTimeseriesPoint> source,DateTime to){DateTime? started=null;long longest=0;foreach(var point in (source??Enumerable.Empty<ApiManager.CameraHealthTimeseriesPoint>()).OrderBy(item=>item.BucketStart)){DateTime time;if(!DateTime.TryParse(point.BucketStart,out time))continue;var unavailable=point.Unavailable>0?point.Unavailable:point.Offline+point.Unknown;if(unavailable>0){if(!started.HasValue)started=time;}else if(started.HasValue){longest=Math.Max(longest,(long)(time-started.Value).TotalSeconds);started=null;}}return started.HasValue?Math.Max(longest,(long)(to-started.Value).TotalSeconds):longest;}
  async Task RefreshCameraAnalysisKpisAsync(){try{var all=(GlobalSystem.Instance.CameraList??new List<Camera>()).Where(camera=>camera!=null&&!string.IsNullOrWhiteSpace(camera.camID)).ToList();var filtered=_appliedCameraIds.Count==0?all:all.Where(camera=>_appliedCameraIds.Contains(camera.camID)).ToList();var ids=filtered.Select(camera=>camera.camID.Trim()).ToList();var from=FromFilter.Value??DateTime.Now.Date;var to=ToFilter.Value??DateTime.Now;if(to<from)to=from;var statusesTask=ApiManager.Instance.GetPortalDeviceStatusBatchAsync(all.Select(camera=>camera.camID.Trim()).ToList(),_lifetime.Token);var trendTask=ApiManager.Instance.GetCameraHealthTimeseriesAsync(from,to,"1h",ids,_lifetime.Token);await Task.WhenAll(statusesTask,trendTask);var statuses=statusesTask.Result??new List<ApiManager.DeviceStatusResponse>();var hasStatuses=statuses.Any(status=>status!=null&&!string.IsNullOrWhiteSpace(status.DeviceId));var online=hasStatuses?statuses.Count(status=>status?.IsOnline==true):all.Count(camera=>camera.is_online==true);var offline=Math.Max(0,all.Count-online);var trend=trendTask.Result?.Data??new List<ApiManager.CameraHealthTimeseriesPoint>();var uptime=trend.Any()?trend.Average(point=>point.UptimePercent??0):0;var disconnects=trend.Any()?trend.Max(point=>point.Unavailable>0?point.Unavailable:point.Offline+point.Unknown):0;CameraAnalysisTotalText.Text=all.Count.ToString("N0");CameraAnalysisOnlineText.Text=online.ToString("N0");CameraAnalysisOfflineText.Text=offline.ToString("N0");CameraAnalysisUptimeText.Text=uptime.ToString("0.0")+"%";CameraAnalysisDisconnectText.Text=disconnects.ToString("N0");CameraAnalysisLongestText.Text=CameraDuration(LongestFilteredUnavailable(trend,to));}catch(OperationCanceledException){}catch(Exception ex){LoggerManager.LogException(ex,"Analysis.RefreshCameraKpis");}}
  static string ResolveCameraTrendBucket(string selected,DateTime from,DateTime to){if(selected=="5 phút")return "5m";if(selected=="1 giờ")return "1h";if(selected=="1 ngày")return "1d";if(selected=="7 ngày")return "7d";var span=to>from?to-from:TimeSpan.Zero;return span.TotalMinutes<=100?"5m":span.TotalHours<=20?"1h":span.TotalDays<=20?"1d":"7d";}
  async Task RefreshCameraTrendAsync(){try{var all=(GlobalSystem.Instance.CameraList??new List<Camera>()).Where(camera=>camera!=null&&!string.IsNullOrWhiteSpace(camera.camID));var ids=(_appliedCameraIds.Count==0?all.Where(camera=>true):all.Where(camera=>_appliedCameraIds.Contains(camera.camID))).Select(camera=>camera.camID.Trim()).ToList();var from=FromFilter.Value??DateTime.Now.Date;var to=ToFilter.Value??DateTime.Now;var selected=(BucketFilter.SelectedItem as ComboBoxItem)?.Content?.ToString()??"Auto";var bucket=ResolveCameraTrendBucket(selected,from,to);var points=(await ApiManager.Instance.GetCameraHealthTimeseriesAsync(from,to,bucket,ids,_lifetime.Token))?.Data??new List<ApiManager.CameraHealthTimeseriesPoint>();if(points.Count>20){var stride=(int)Math.Ceiling(points.Count/20d);points=points.Where((point,index)=>index%stride==0).Take(20).ToList();}_cameraTrendLabels.Clear();_cameraTrendOnline.Clear();_cameraTrendOffline.Clear();_cameraTrendUptime.Clear();_cameraRecentIncidents.Clear();foreach(var point in points){DateTime time;DateTime.TryParse(point.BucketStart,out time);var unavailable=point.Unavailable>0?point.Unavailable:point.Offline+point.Unknown;_cameraTrendLabels.Add((time==DateTime.MinValue?DateTime.Now:time).ToString(bucket=="1d"||bucket=="7d"?"dd/MM":"HH:mm"));_cameraTrendOnline.Add(point.Online);_cameraTrendOffline.Add(unavailable);_cameraTrendUptime.Add(point.UptimePercent??0);}foreach(var point in points.Where(item=>(item.Unavailable>0?item.Unavailable:item.Offline+item.Unknown)>0).OrderByDescending(item=>item.BucketStart).Take(10)){DateTime time;DateTime.TryParse(point.BucketStart,out time);var count=point.Unavailable>0?point.Unavailable:point.Offline+point.Unknown;_cameraRecentIncidents.Add(new CameraRecentIncident{Title="Sự cố mất kết nối",TimeText=time==DateTime.MinValue?"Không có thời điểm":time.ToString("HH:mm:ss dd-MM-yyyy"),Detail="Phát hiện trong khung dữ liệu "+bucket,Badge=count+" camera"});}}catch(Exception ex){LoggerManager.LogException(ex,"Analysis.RefreshCameraTrend");}}
  async Task RefreshCameraAnalysisDataAsync(){SetCameraRecentIncidentListVisibility(Visibility.Hidden);try{await RefreshCameraAnalysisAsync();CaptureCameraStatusRows();await RefreshCameraAnalysisKpisAsync();await RefreshCameraTrendAsync();await RefreshCameraRecentIncidentsAsync();RestoreCameraKpiLabels();SetCameraAnalysisUpdated();}finally{SetCameraRecentIncidentListVisibility(Visibility.Visible);}}
