  async Task RefreshCameraRecentIncidentsAsync(){try{var allowed=new HashSet<string>((_appliedCameraIds.Count==0?(GlobalSystem.Instance.CameraList??new List<Camera>()).Where(camera=>camera!=null).Select(camera=>camera.camID):_appliedCameraIds).Where(id=>!string.IsNullOrWhiteSpace(id)).Select(id=>id.Trim()),StringComparer.OrdinalIgnoreCase);var now=DateTime.Now;var cameras=await ApiManager.Instance.GetCameraHealthAttentionCamerasAsync(10,_lifetime.Token);_cameraRecentIncidents.Clear();foreach(var camera in (cameras??new List<ApiManager.CameraHealthAttentionCamera>()).Where(camera=>camera!=null).Where(camera=>allowed.Count==0||allowed.Contains((camera.CameraId??camera.CameraCode??string.Empty).Trim())).OrderByDescending(camera=>camera.UnavailableSeconds??0).Take(10)){var seconds=Math.Max(0,camera.UnavailableSeconds??0);var cameraId=string.IsNullOrWhiteSpace(camera.CameraId)?camera.CameraCode:camera.CameraId;var start=now.AddSeconds(-seconds);_cameraRecentIncidents.Add(new CameraRecentIncident{Title=string.IsNullOrWhiteSpace(cameraId)?"Camera không xác định":cameraId,TimeText=seconds>0?start.ToString("HH:mm:ss dd-MM-yyyy")+" → Hiện tại":"Hiện tại",Detail="not_ready",Badge=CameraDuration(seconds)});}}catch(OperationCanceledException){}catch(Exception ex){LoggerManager.LogException(ex,"Analysis.RefreshCameraRecentIncidents");}}
