  void UpdateCameraStatusScrollBar(){if(_cameraStatusScrollBar==null)return;_cameraStatusScrollBar.Maximum=Math.Max(1,_cameraStatusRows.Count-_cameraStatusPageSize);_cameraStatusScrollBar.ViewportSize=Math.Max(1,_cameraStatusPageSize);_cameraStatusScrollBar.LargeChange=Math.Max(1,_cameraStatusPageSize);_cameraStatusScrollBar.SmallChange=1;_cameraStatusScrollBar.Visibility=Visibility.Visible;}
  void ForceCameraStatusViewport(){if(CameraAnalysisGrid==null)return;CameraAnalysisGrid.Height=360;CameraAnalysisGrid.MaxHeight=360;CameraAnalysisGrid.MinHeight=0;CameraAnalysisGrid.SetValue(ScrollViewer.VerticalScrollBarVisibilityProperty,ScrollBarVisibility.Visible);ScrollViewer.SetVerticalScrollBarVisibility(CameraAnalysisGrid,ScrollBarVisibility.Visible);CameraAnalysisGrid.SetValue(DataGrid.HorizontalContentAlignmentProperty,HorizontalAlignment.Stretch);EnsureCameraStatusScrollBar();CameraAnalysisGrid.ApplyTemplate();CameraAnalysisGrid.Dispatcher.BeginInvoke(new Action(()=>{CameraAnalysisGrid.ApplyTemplate();foreach(var bar in FindVisualChildren<ScrollBar>(CameraAnalysisGrid).Where(item=>item.Orientation==Orientation.Vertical)){bar.Visibility=Visibility.Visible;bar.Width=12;bar.MinWidth=12;bar.Background=new SolidColorBrush(Color.FromRgb(13,35,52));}}),DispatcherPriority.ContextIdle);}
  void CaptureCameraStatusRows(){_cameraStatusRows=(CameraAnalysisGrid?.ItemsSource as IEnumerable<AnalysisCameraRow>??Enumerable.Empty<AnalysisCameraRow>()).ToList();foreach(var row in _cameraStatusRows)row.NoteBrush=new SolidColorBrush(row.Status!=null&&row.Status.Contains("Trực tuyến")?Color.FromRgb(39,201,109):Color.FromRgb(255,96,122));_cameraStatusPage=1;RenderCameraStatusPage();}
  void RenderCameraStatusPage(){if(CameraAnalysisGrid==null||_cameraStatusInfo==null)return;UpdateCameraStatusScrollBar();IEnumerable<AnalysisCameraRow> sorted;switch(_cameraStatusSortMember){case "Status":sorted=_cameraStatusRows.OrderBy(row=>row.Status??string.Empty,StringComparer.OrdinalIgnoreCase);break;case "ActivityPercent":sorted=_cameraStatusRows.OrderBy(row=>row.ActivityPercent);break;case "Note":sorted=_cameraStatusRows.OrderBy(row=>CameraStatusDurationValue(row.Note));break;case "Median":sorted=_cameraStatusRows.OrderBy(row=>row.Median??string.Empty,StringComparer.OrdinalIgnoreCase);break;case "ThresholdText":sorted=_cameraStatusRows.OrderBy(row=>CameraStatusDurationValue(row.ThresholdText));break;default:sorted=_cameraStatusRows.OrderBy(row=>row.CameraId??string.Empty,StringComparer.OrdinalIgnoreCase);break;}if(_cameraStatusSortDescending)sorted=sorted.Reverse();var rows=sorted.ToList();var total=rows.Count;var pages=Math.Max(1,(int)Math.Ceiling(total/(double)_cameraStatusPageSize));_cameraStatusPage=Math.Max(1,Math.Min(_cameraStatusPage,pages));var start=total==0?0:(_cameraStatusPage-1)*_cameraStatusPageSize;var end=Math.Min(total,start+_cameraStatusPageSize);CameraAnalysisGrid.ItemsSource=rows.Skip(start).Take(_cameraStatusPageSize).ToList();_cameraStatusInfo.Text=total==0?"Không có camera":"Hiển thị "+(start+1)+"–"+end+" của "+total;_cameraStatusPageText.Text=_cameraStatusPage+" / "+pages;_cameraStatusPrevious.IsEnabled=_cameraStatusPage>1;_cameraStatusNext.IsEnabled=_cameraStatusPage<pages;}
  static IEnumerable<T> FindVisualChildren<T>(DependencyObject root) where T:DependencyObject{if(root==null)yield break;for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);var value=child as T;if(value!=null)yield return value;foreach(var descendant in FindVisualChildren<T>(child))yield return descendant;}}
